        stack = []
        for char in s:
            if char == '(':
                stack.append(char)
            elif char == ')':
                if not stack:
                    return False
                stack.pop()
        return len(stack) == 0

    if len(lst) != 2:
        return 'No'

    open_count1, close_count1 = count_parens(lst[0])
    open_count2, close_count2 = count_parens(lst[1])

    if open_count1 != close_count1 or open_count2 != close_count2:
        return 'No'

    concatenated = lst[0] + lst[1]

    return 'Yes' if is_balanced(concatenated) else 'No'

